import numpy as np
from sklearn.linear_model import Ridge
from mne.decoding import ReceptiveField, TimeDelayingRidge


def stim(n_t: int, n_f: int):
    X = np.empty((n_t, n_f))
    for t in range(n_t):
        for f in range(n_f):
            X[t, f] = np.sin(0.37 * t * (f + 1) + f) + 0.5 * np.cos(0.11 * t + 2.0 * f)
    return X


def close(a, b, rtol: float = 1e-9, atol: float = 0.0) -> bool:
    x = np.asarray(a, dtype=float).ravel()
    z = np.asarray(b, dtype=float).ravel()
    if x.shape[0] != z.shape[0]:
        print("length mismatch", x.shape[0], z.shape[0])
        return False
    scale = float(np.max(np.abs(z))) if z.shape[0] > 0 else 0.0
    for i in range(x.shape[0]):
        if abs(x[i] - z[i]) > atol + rtol * max(abs(z[i]), 1e-6 * scale):
            print("mismatch at", i, x[i], z[i])
            return False
    return True


@test
def test_receptive_field():
    X = stim(200, 3)
    w = np.array([[0.5, -0.2, 0.1, 0.3], [0.0, 0.4, -0.3, 0.2], [0.1, 0.1, 0.2, -0.5]])
    y = np.zeros(200)
    for f in range(3):
        y += np.convolve(X[:, f].copy(), w[f].copy())[:200]
    for i in range(200):
        y[i] += 0.05 * np.sin(i * 1.3)
    rf = ReceptiveField(-0.01, 0.02, 100.0, estimator=1.0, patterns=True)
    rf.fit(X, y)
    assert close(rf.delays_, [-1.0, 0.0, 1.0, 2.0])
    assert close(rf.coef_, [0.11337616429767602, 0.00411522798592465, 0.15639827882854973, 0.36625978732553427, -0.06777981480204266, 0.08642399204633619, 0.14171243038299003, -0.011132448069993599, -0.3950925361974241, 0.2846882697146386, 0.3409954260748608, -0.4058081242621322], 1e-8)
    assert close(rf.patterns_, [0.0014414378047924205, 0.0017568491594481175, 0.001870501425625962, 0.0017853408014420532, -0.00012240306930392866, 0.0002124113066755685, 0.00038074963388821893, 0.0003336737891317546, -0.0005426396830005046, 0.0008706377253142305, 0.0008984426439510666, -0.0005096357421859243], 1e-8)
    assert close(rf.predict(X)[::17], [0.3800618338771759, 0.21400077859670075, 0.17180756619221765, 0.7475834044341368, 0.4695826297701684, 0.07627963567958661, 0.6040728350555026, 0.703509079027876, 0.13371560298353402, 0.3861426092310633, 0.8224234011503254, 0.3274354968736423], 1e-8)
    assert close(rf.score(X, y), [0.9961199981573953], 1e-8)
    rfc = ReceptiveField(0.0, 0.03, 100.0, estimator=0.5, scoring="corrcoef", fit_intercept=False)
    rfc.fit(X, y)
    assert close(rfc.coef_, [0.27123066343375524, 0.11204497157172995, 0.08872880403264927, 0.18251169602152068, 0.09451068729072828, 0.08516305729561492, 0.05130203114627488, 0.02530453478921503, -0.012459335577918786, 0.2701178968583173, 0.022917576406951797, -0.4281853839141069], 1e-8)
    assert close(rfc.score(X, y), [0.9985706886867557], 1e-8)
    rfr = ReceptiveField(-0.02, 0.01, 100.0, estimator=Ridge(alpha=2.0), patterns=True)
    rfr.fit(X, y)
    assert close(rfr.coef_, [-0.045744683976161014, -0.027841471472037763, 0.05793213146228237, 0.5664838379216646, -0.16574332951312565, 0.06750180375750833, 0.07398471841061466, 0.03130586048520546, -0.4516774245320076, -0.0048416273759200965, 0.2406509133338603, -0.022593138427527127], 1e-8)
    assert close(rfr.patterns_, [0.0010110066864018417, 0.0014457284629642055, 0.0017540272853808299, 0.0018458979946896633, -0.00045907714126939913, -0.0001274940180647828, 0.0002108571680231381, 0.00038276133161687986, -0.0017297603369711236, -0.0005523477017665368, 0.0008656728618776231, 0.0009081759142546594], 1e-8)
    assert close(rfr.predict(X)[::19], [0.6567562801081852, -0.15895253221578226, 0.17865155546346123, 1.2879081517610753, -0.4245302714439913, 0.03263269264555817, 0.39056859091157076, -1.5873556671611453, -0.28989647048298733, 0.7522106478090173, -0.31617999461576407], 1e-8)
    assert close(rfr.score(X, y), [0.9937912213729022], 1e-8)


@test
def test_time_delaying_ridge():
    X3 = np.empty((120, 3, 2))
    for e in range(3):
        X3[:, e, :] = stim(120, 2) * (1 + 0.1 * e)
    Y3 = np.empty((120, 3, 2))
    for t in range(120):
        for e in range(3):
            Y3[t, e, 0] = X3[t, e, 0] * 0.7 - 0.3 * X3[(t - 1) % 120, e, 1]
            Y3[t, e, 1] = X3[t, e, 1] * 0.2
    tdr = TimeDelayingRidge(0.0, 0.02, 100.0, alpha=3.0, reg_type="laplacian")
    tdr.fit(X3, Y3)
    assert close(tdr.coef_, [0.5498097493648147, 0.21958208924896608, -0.0888206445948314, -0.0842403977911007, -0.1557331037832126, -0.09189417684468168, 0.007377129735985403, -0.00341764676543163, -0.004346484896955975, 0.16449940822188985, 0.05111034702076544, -0.02993983972831587], 1e-8)
    assert close(tdr.intercept_, [0.0002485822812962439, -9.976625463579774e-05], 1e-8, 1e-12)
    assert close(tdr.predict(X3)[::13], [0.22179579399893698, 0.1077823234774385, 0.24395051517070104, 0.118570532450646, 0.26610523634246513, 0.12935874142385337, -0.35329482271220597, -0.2743270122295516, -0.38864916321155607, -0.3017497368270432, -0.4240035037109064, -0.32917246142453466, -0.6156277508370284, 0.20516308497257463, -0.677215384148861, 0.2256893700952957, -0.7388030174606933, 0.2462156552180167, 0.5696741721717904, -0.10624509079789102, 0.6266167311608398, -0.11685962325221658, 0.6835592901498889, -0.12747415570654202, 0.24686792316974918, 0.21245054064328328, 0.27152985725859435, 0.23370557133307507, 0.2961917913474398, 0.25496060202286697, 0.026309012550361815, -0.2744720172757601, 0.02891505557726874, -0.30190924237787253, 0.031521098604174944, -0.3293464674799851, -0.7876878592440787, 0.12558053052683313, -0.8664815033966161, 0.13814856020498, -0.9452751475491536, 0.15071658988312697, 0.41743435956402203, -0.06518059830254996, 0.45915293729229445, -0.07168868150734137, 0.5008715150205671, -0.07819676471213269, 0.21779100038376956, 0.1766775381595559, 0.23954524219401643, 0.1943552686009751, 0.26129948400426395, 0.21203299904239412, 0.22747748956156347, -0.13959356712754944, 0.25020038028959046, -0.15354294721484088, 0.27292327101761715, -0.16749232730213223], 1e-8)
    tdr2 = TimeDelayingRidge(-0.02, 0.01, 100.0, alpha=1.0, reg_type=("ridge", "laplacian"), fit_intercept=False)
    tdr2.fit(X3, Y3)
    assert close(tdr2.coef_, [-0.0027681900844409107, 0.10873279951164001, 0.4970176780866195, 0.10732485358870313, 0.05101211054345711, -0.11219145753271992, 0.10383676288733974, -0.33484366235332197, -0.00803540770927852, -0.026079671019644698, 0.06925108134067211, -0.04052349161908115, -0.016773558951764297, 0.041318802990523554, 0.15750354824807145, 0.017192756602544837], 1e-8)


test_receptive_field()
